DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.payroll_preview(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'AS $function$','AS $function$'||chr(10)||'#variable_conflict use_column'||chr(10));def:=replace(def,'SELECT e.* FROM public.hr_employees e WHERE e.tenant_id=t AND public.people_person_access(t,e.id,auth.uid()) AND EXISTS(SELECT 1 FROM public.hr_payroll p WHERE p.tenant_id=t AND p.employee_id=e.id AND year=y AND month=m) AND NOT(e.hire_date<=last_day AND (e.end_date IS NULL AND e.status IN (''active'',''on_leave'') OR e.end_date>=first_day))','SELECT emp.* FROM public.hr_employees emp WHERE emp.tenant_id=t AND public.people_person_access(t,emp.id,auth.uid()) AND EXISTS(SELECT 1 FROM public.hr_payroll saved WHERE saved.tenant_id=t AND saved.employee_id=emp.id AND year=y AND month=m) AND NOT(emp.hire_date<=last_day AND (emp.end_date IS NULL AND emp.status IN (''active'',''on_leave'') OR emp.end_date>=first_day))');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_approve(uuid,integer,integer,integer)'::regprocedure) INTO def;def:=replace(def,'AS $function$','AS $function$'||chr(10)||'#variable_conflict use_column'||chr(10));EXECUTE def;END $$;
CREATE FUNCTION public.payroll_apply_repeats(t uuid,y integer,m integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;p public.hr_payroll;earned numeric;gross numeric;ee numeric;er numeric;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'Payroll manager required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN RETURN;END IF;
FOR r IN SELECT DISTINCT ON(a.employee_id,a.field) a.* FROM public.hr_payroll_overrides a JOIN public.hr_payroll prev ON prev.id=a.payroll_id AND prev.tenant_id=t WHERE a.tenant_id=t AND make_date(prev.year,prev.month,1)<make_date(y,m,1) ORDER BY a.employee_id,a.field,prev.year DESC,prev.month DESC,a.created_at DESC LOOP
IF NOT r.repeat THEN CONTINUE;END IF;SELECT * INTO p FROM public.hr_payroll WHERE tenant_id=t AND employee_id=r.employee_id AND year=y AND month=m FOR UPDATE;IF p.id IS NULL OR p.accrual_journal_entry_id IS NOT NULL OR p.preparation IS NULL OR NOT public.people_person_access(t,p.employee_id,auth.uid()) OR EXISTS(SELECT 1 FROM public.hr_payroll_overrides WHERE tenant_id=t AND payroll_id=p.id AND field=r.field) THEN CONTINUE;END IF;
EXECUTE format('UPDATE public.hr_payroll SET %I=$1 WHERE id=$2 AND tenant_id=$3',r.field) USING r.new_value,p.id,t;
INSERT INTO public.hr_payroll_overrides(tenant_id,employee_id,payroll_id,field,previous_value,new_value,reason,repeat,created_by) VALUES(t,p.employee_id,p.id,r.field,COALESCE((to_jsonb(p)->>r.field)::numeric,0),r.new_value,'Repeating: '||left(r.reason,2900),true,r.created_by);
SELECT * INTO p FROM public.hr_payroll WHERE id=p.id AND tenant_id=t;earned:=COALESCE(p.earned_salary_override,p.actual_base_salary,p.forecast_base_salary);gross:=earned+COALESCE(p.actual_overtime,0)+COALESCE(p.actual_bonus,0)+p.annual_leave_pay-p.unpaid_leave_deduction+COALESCE(p.adjustments_override,0);ee:=COALESCE(p.mpf_employee_override,least(1500,gross*0.05));er:=COALESCE(p.mpf_employer_override,least(1500,gross*0.05));UPDATE public.hr_payroll SET gross_salary=gross,mpf_employee=ee,mpf_employer=er,net_salary=gross-ee-p.other_deductions,total_deductions=ee+p.other_deductions,mpf_payment_amount=ee+er WHERE id=p.id AND tenant_id=t;
END LOOP;END $$;
REVOKE ALL ON FUNCTION public.payroll_apply_repeats(uuid,integer,integer) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.payroll_prepare(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'INSERT INTO public.hr_payroll_months(tenant_id,year,month,prepared_by,prepared_at,revision)','PERFORM public.payroll_apply_repeats(t,y,m); INSERT INTO public.hr_payroll_months(tenant_id,year,month,prepared_by,prepared_at,revision)');EXECUTE def;END $$;